import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.eFe5Lsvn.js";const f=JSON.parse('{"title":"Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/conventions.md","filePath":"reference/conventions.md"}'),s={name:"reference/conventions.md"};function a(i,e,d,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h1><p>These apply to the app&#39;s files and to MayhemLib. Getting one wrong usually shows up as a robot that drives mirrored or in the wrong place.</p><ul><li><strong>Coordinates.</strong> WPILib blue-origin field frame. +x points from the blue wall toward the red wall, +y points left from the blue driver station, and headings are CCW-positive radians. The pose supplier must return the blue-origin pose <strong>on both alliances</strong>, which is what CTRE&#39;s <code>getState().Pose</code> returns.</li><li><strong>Speeds.</strong> <code>DriveCommand.fieldSpeeds</code> are field-relative. Use <code>DriveCommand.robotSpeeds(heading)</code> if your drivetrain wants robot-relative speeds.</li><li><strong>Forces.</strong> <code>DriveCommand.wheelForceX/Y</code> are per-module forces in the <strong>field frame</strong>, in newtons. This matches what CTRE&#39;s <code>ApplyFieldSpeeds.withWheelForceFeedforwardsX/Y</code> expects.</li><li><strong>Module order.</strong> <strong>FL, FR, BL, BR.</strong> This is the Tuner X order in <code>new CommandSwerveDrivetrain(constants, FrontLeft, FrontRight, BackLeft, BackRight)</code>. The robot in the Mayhem app must use the same order. If the trajectory&#39;s force arrays don&#39;t match <code>FollowerConfig.modules</code>, the force feedforward is dropped (sent as zeros).</li><li><strong>Headings in samples</strong> are unwrapped (continuous). <code>TrajectorySample.getPose()</code> wraps them.</li><li><strong>Alliance.</strong> Paths are authored on blue and flipped using the field symmetry stored in the file. See <a href="/Mayhem/lib/splits-and-alliance#alliance-flipping">Splits and alliance flipping</a>.</li></ul>',3)])])}const m=o(s,[["render",a]]);export{f as __pageData,m as default};
